const aspectModes = {};
function aspectKey(a){return aspectModes[a.id] || a.defaultAspect || (a.constraints?.width>a.constraints?.height?'landscape':'portrait');}
function aspectAsset(a){const key=aspectKey(a),v=a.aspectVariants?.[key];return v?{...a,...v,id:a.id,aspectVariants:a.aspectVariants,selectedAspect:key}:a;}
function aspectControls(a){if(!a.aspectVariants)return '';return `<div class="aspect-variants" role="group" aria-label="画幅">${[['landscape','横屏 16:9'],['portrait','竖屏 9:16']].filter(([k])=>a.aspectVariants[k]).map(([k,label])=>`<button class="button ${aspectKey(a)===k?'primary':''}" data-action="preview-aspect" data-id="${esc(a.id)}" data-value="${k}">${label}</button>`).join('')}</div>`;}

