let saved;try{saved=JSON.parse(localStorage.getItem('motion-archive-v1'))}catch{}
let assets=[];let folders=Array.isArray(saved?.folders)?saved.folders:['产品演示','文字演绎','UI 操作'];
let state={section:'all',tab:'all',query:'',tag:'',filter:false,view:'grid',sort:'curated',selected:'c1',detailTab:'info',folder:null,smart:null,detail:true};
let modal=null,draft=null,editorTab='content',playing=true,progress=0,last=0,toastTimer;
const $=s=>document.querySelector(s);
let saveQueue=Promise.resolve();
function persist(){const payload={items:structuredClone(assets),folders:[...folders]};saveQueue=saveQueue.then(async()=>{const r=await fetch('/api/library',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error((await r.json()).error||'保存失败');}).catch(e=>toast('未保存：'+e.message));return saveQueue;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function getAsset(){return assets.find(a=>a.id===state.selected)}
function badge(t){return /轻盈|浅色|卡片/.test(t)?'green':/空间|界面/.test(t)?'blue':/文字|反馈/.test(t)?'peach':''}
function art(a,preview=false){a=aspectAsset(a);if(a.file){if(a.type==='font')return `<div class="art font-sample" style="font-family:${esc(a.fontFamily)}"><small>自定义字体</small><strong>${esc(a.config.sample).replace(/\n/g,'<br>')}</strong></div>`;return `<div class="art imported-background">${a.mediaKind==='video'?`<video src="${esc(a.file)}" ${preview?'controls':''} muted loop playsinline preload="metadata" style="object-fit:${a.config.fit}"></video>`:`<img src="${esc(a.file)}" alt="${esc(a.name)}" style="object-fit:${a.config.fit}">`}</div>`;}if(a.productionReady){if(a.type==='style')return styleArt(a);return `${preview?aspectControls(a):''}${preview&&a.motionOnly?`<div class="preview-variants"><button class="button ${previewModes[a.id]!=='styled'?'primary':''}" data-action="preview-mode" data-id="${esc(a.id)}" data-value="motion">纯动效</button><button class="button ${previewModes[a.id]==='styled'?'primary':''}" data-action="preview-mode" data-id="${esc(a.id)}" data-value="styled">复刻版</button></div>`:''}<div class="art production-video" style="aspect-ratio:${a.constraints?.width||720}/${a.constraints?.height||1280}"><video src="${esc(a.motionOnly&&previewModes[a.id]!=='styled'?a.motionOnly.preview:a.preview)}#t=0.8" ${preview?'controls':''} muted playsinline preload="metadata" loop aria-label="${esc(a.name)}预览"></video></div>`;}let html='';const title=esc(a.config?.title||'Make it\nmove.').split('\n');
 switch(a.art){
 case 'make':html=`<div class="art-label">TYPE IN MOTION</div><div class="huge moving">${title[0]}<br><em>${title.slice(1).join('<br>')||'move.'}</em></div><div class="mini-cursor"></div><div class="art-index">01 — EXPAND</div>`;break;
 case 'flow':html=`<div class="rings moving">${Array.from({length:6},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="flow-word"><span>Flow.</span></div><div class="art-label">A CONTINUOUS MOTION</div>`;break;
 case 'grid':html=`<div class="bigword moving">${esc(a.config?.title||'Ideas into\naction.').replace(/\n/g,'<br>')}</div><div class="grid-tiles">${['spark','layers','arrow'].map(n=>`<i class="moving">${icon(n)}</i>`).join('')}</div>`;break;
 case 'orb':html='<div class="orb moving"></div><div class="orb-label">Softly, in focus.</div><div class="art-label" style="color:#eee">LIGHT STUDY / 004</div>';break;
 case 'feedback':html='<div class="terminal moving">› npm test<b>PASS</b><div class="code">All systems, connected.</div></div>';break;
 case 'stack':html=`${[1,2,3].map((n)=>`<div class="stack-card"><small>ARCHIVE / 0${n}</small>${n===3?'<strong>New<br>perspective.</strong>':''}</div>`).join('')}`;break;
 case 'type':html=`<div class="type-lines moving">${esc(a.config?.title||'Less.\nMore.').split('\n').map((s,i)=>`<div class="${i?'outline':''}">${s}</div>`).join('')}</div>`;break;
 case 'gradient':html='<div class="gradient-wave moving"></div><div class="gradient-word">A quieter space.</div>';break;
 case 'layout':html='<div class="layout-shapes moving"><i></i><i></i><i></i></div>';break;
 case 'image':html=`<img src="${esc(a.image)}" alt="${esc(a.name)}">`;break;
 }
 let bg=a.config?.bg==='warm'?'background:#ddd0bb':a.config?.bg==='dark'?'background:#222b30':a.config?.bg==='sage'?'background:#c5d0bd':'';
 return `<div class="art art-${a.art}" style="--art-accent:${esc(a.config?.accent||'#8773b2')};${bg}" ${preview?'data-preview="true"':''}>${html}</div>`;
}
function filtered(){let a=assets.filter(a=>state.folder?a.folders.includes(state.folder):state.smart==='draft'?!a.productionReady&&!a.callable:state.smart==='ready'?a.productionReady:state.section==='all'?true:a.type===state.section);if(state.tab==='fav')a=a.filter(x=>x.fav);if(state.tag)a=a.filter(x=>x.tags.includes(state.tag));const q=state.query.toLowerCase();if(q)a=a.filter(x=>[x.name,x.desc,...x.tags,...x.folders,x.usageContract?.summary,...(x.usageContract?.keywords||[]),...(x.usageContract?.useWhen||[])].join(' ').toLowerCase().includes(q));if(state.sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name,'zh-CN'));if(state.sort==='duration')a.sort((x,y)=>x.duration-y.duration);if(state.sort==='recent'||state.tab==='recent')a.sort((x,y)=>y.created-x.created);return a}
function nav(type){return `<button class="nav-item ${state.section===type&&!state.folder&&!state.smart?'active':''}" data-action="section" data-value="${type}">${icon(types[type]?.[1]||'grid')}<span>${types[type]?.[0]||'全部资产'}</span><span class="nav-count">${assets.filter(a=>type==='all'||a.type===type).length}</span></button>`}
function sidebar(){return `<aside class="sidebar"><div class="workspace-name">Motion Archive</div><div class="workspace-sub">把好动效，留在手边。</div><div class="nav-section"><div class="section-label">工作流程</div><a class="nav-item" href="/workflow.html">${icon('play')}复现项目 / 待入库</a></div><div class="nav-section"><div class="section-label">正式资产</div>${['all','style','template','font','background'].map(nav).join('')}</div><div class="nav-section"><div class="section-label">我的文件夹<button aria-label="新建文件夹" data-action="new-folder">${icon('plus')}</button></div>${folders.map((f,i)=>`<button class="nav-item ${state.folder===f?'active':''}" data-action="folder" data-value="${esc(f)}">${icon('folder')}${esc(f)}<span class="nav-count">${assets.filter(a=>a.folders.includes(f)).length}</span></button>`).join('')}</div><div class="nav-section"><div class="section-label">资源状态</div><button class="nav-item" data-action="smart" data-value="ready">${icon('check')}已确认源码</button><button class="nav-item" data-action="smart" data-value="draft">${icon('clock')}演示与调校草稿</button></div><div class="sidebar-bottom"><div class="local"><i></i>统一资源库 · 本地文件保存</div><a href="/workflow.html?page=integration">AI 调用与导出 ↗</a></div></aside>`}
function card(a){return `<article class="asset-card ${state.selected===a.id?'selected':''}" data-action="select" data-id="${a.id}" tabindex="0" aria-label="查看 ${esc(a.name)}"><div class="art-wrap">${art(a)}<button class="asset-preview-open" data-action="preview" data-id="${esc(a.id)}" aria-label="放大预览 ${esc(a.name)}">${icon('expand')}<span>预览</span></button></div><span class="asset-duration">${a.duration.toFixed(1)}s</span><div class="card-top-actions"><button class="favorite-btn ${a.fav?'is-fav':''}" data-action="favorite" data-id="${a.id}" aria-label="${a.fav?'取消收藏':'收藏'} ${esc(a.name)}">${icon('star')}</button></div><div class="card-content"><div class="card-title">${esc(a.name)}<button class="asset-delete" data-action="delete-asset" data-id="${esc(a.id)}" aria-label="删除 ${esc(a.name)}">删除</button></div><div class="card-subtitle">${esc(a.desc)}</div><div class="card-tags">${a.aspectVariants?'<span class="chip blue">'+Object.keys(a.aspectVariants).map(k=>k==='landscape'?'横屏':k==='portrait'?'竖屏':k).join(' / ')+'</span>':a.aspectSupport==='universal'?'<span class="chip gray">横竖屏通用</span>':''}${a.tags.map(t=>`<span class="chip ${badge(t)}">${esc(t)}</span>`).join('')}</div></div><div class="card-foot"><span><i class="status-dot ${a.status==='调校中'?'draft':''}"></i>${a.status} · v${a.version}</span><span class="asset-type">${types[a.type]?.[2]||'ASSET'}</span></div></article>`}
function main(){const data=filtered();const title=state.folder||(state.smart==='ready'?'已确认源码':state.smart==='draft'?'演示与调校草稿':types[state.section]?.[0]||'全部资产');return `<main class="main"><header class="main-header"><div class="breadcrumb">正式资产 ${icon('chevron')} <b>${esc(title)}</b></div><div class="title-row"><div class="title-main"><h1>${esc(title)}</h1><span class="count-pill">${data.length}</span></div><div class="header-actions"><button class="button" data-action="import">${icon('upload')}导入</button><button class="button primary" data-action="new-combo">${icon('plus')}新建动效模板</button></div></div><p class="description">${state.section==='template'&&!state.folder&&!state.smart?'让风格、布局与动作，在这里成为可以复用的灵感。':'收藏、归类和调校，让下一次创作从这里开始。'}</p><div class="tabs"><button class="tab ${state.tab==='all'?'active':''}" data-action="tab" data-value="all">${icon('grid')}全部资产</button><button class="tab ${state.tab==='recent'?'active':''}" data-action="tab" data-value="recent">${icon('clock')}最近添加</button><button class="tab ${state.tab==='fav'?'active':''}" data-action="tab" data-value="fav">${icon('star')}已收藏</button><span class="tab-end"><span class="green-dot"></span>统一资产管理</span></div></header><div class="toolbar"><div class="search-inline">${icon('search')}<input id="search" placeholder="搜索名称、标签或用途…" value="${esc(state.query)}" aria-label="搜索资产"></div><button class="button filter-btn ${state.filter||state.tag?'on':''}" data-action="filter">${icon('filter')}筛选${state.tag?' · 1':''}</button><select id="sort" class="sort" aria-label="排序"><option value="curated" ${state.sort==='curated'?'selected':''}>默认排序</option><option value="recent" ${state.sort==='recent'?'selected':''}>最近添加</option><option value="name" ${state.sort==='name'?'selected':''}>名称排序</option><option value="duration" ${state.sort==='duration'?'selected':''}>时长优先</option></select><div class="view-toggle"><button class="${state.view==='grid'?'active':''}" data-action="view" data-value="grid" aria-label="网格视图">${icon('grid')}</button><button class="${state.view==='list'?'active':''}" data-action="view" data-value="list" aria-label="列表视图">${icon('list')}</button></div></div>${state.filter?`<div class="filters"><span>按标签筛选</span>${['全部','文字演绎','空间运镜','轻盈','柔和','界面操作','高对比'].map(t=>`<button class="tag-button ${state.tag===(t==='全部'?'':t)?'active':''}" data-action="tag" data-value="${t==='全部'?'':t}">${t}</button>`).join('')}</div>`:''}<div class="asset-grid ${state.view==='list'?'list-mode':''}">${data.length?data.map(card).join(''):`<div class="empty">${icon('search')}<b>这里还没有匹配的资产</b>${state.section==='reference'?'导入图片参考，开始积累你的素材。':'试试其他关键词，或清除筛选条件。'}<br><button class="button" data-action="clear">清除筛选</button></div>`}</div><div class="grid-footer"><span>${data.length} 项资产${state.tag?' · '+esc(state.tag):''}</span><span>双击资产，进入调校预览 ↗</span></div></main>`}
function legacySpecification(a){a=aspectAsset(a);if(a.file)return {schemaVersion:'motion-library-2',aspectSupport:a.aspectSupport||(a.type==='font'?'universal':undefined),id:a.id,type:a.type,name:a.name,version:a.version,file:{url:new URL(a.file,location.origin).href,relativePath:a.file.slice(1),originalName:a.originalName},...(a.type==='font'?{fontFace:{family:a.fontFamily,source:new URL(a.file,location.origin).href},css:{fontFamily:a.fontFamily}}:{mediaKind:a.mediaKind,remotion:{component:a.mediaKind==='video'?'OffthreadVideo':'Img',src:a.file.slice(1),style:{width:'100%',height:'100%',objectFit:a.config.fit},...(a.mediaKind==='video'?{muted:true,loop:true}:{})}}),note:'将文件复制到 Remotion 工程 public 目录的相同相对路径，通过 staticFile(relativePath) 读取；字体先用 FontFace 加载后渲染。localhost URL 仅本机可访问。'};if(a.productionReady&&a.type==='template'&&a.motionOnly)return {schemaVersion:'motion-library-4',aspect:aspectKey(a),composition:a.constraints,availableAspects:Object.keys(a.aspectVariants||{}),aspectPolicy:'Use the selected source package. Other ratios require a new layout adaptation.',id:a.id,type:a.type,name:a.name,version:a.version,mode:'motion-only',runtime:a.motionOnly.runtime,package:a.motionOnly.package,preview:a.motionOnly.preview,motionContract:a.motionOnly.contract,styleBinding:{required:false,referenceAssetIds:(a.dependencies||[]).map(d=>d.id)},styledReference:{runtime:a.runtime,package:a.package,preview:a.preview,usageConfig:a.usageConfig||{}},editable:{mode:'source',compositionProps:false},note:'默认入口为几何动效版。沿用已确认版本的运动代码，去掉可见字体、图片和表面材质；使用新风格需在源码中替换几何绘制层。不是适配任意布局的通用物理引擎。'};if(a.productionReady)return {schemaVersion:'motion-library-2',aspectSupport:a.aspectSupport||(a.type==='font'?'universal':undefined),id:a.id,type:a.type,name:a.name,version:a.version,runtime:a.runtime,package:a.package,preview:a.preview,source:a.source,segment:a.segment,components:a.components,styleSpec:a.type==='style'?resolvedStyle(a):undefined,usageConfig:a.usageConfig||{},productionReady:true,note:'usageConfig 为保存的使用偏好，不保证源码已接入；实际可传参数见 usageContract。'};return {schemaVersion:'prototype-0.1',kind:'asset-configuration',id:a.id,name:a.name,desc:a.desc,art:a.art,...(a.image?{image:a.image}:{}),type:a.type,version:a.version,durationSeconds:a.duration,tags:a.tags,folders:a.folders,config:a.config,previewRenderer:'css-demo-v1',productionReady:false,note:'交互原型的配置快照，尚不包含生产级 Remotion 运行组件。'}}
function specification(a){const config=legacySpecification(a);return {...config,usageContract:a.usageContract,usageStatus:a.usageStatus,note:(config.note||'')+' 参数支持级别以 usageContract.parameters 的 mode 和 binding 为准；source-edit 不会直接作为 Remotion props 生效。'};}
function usageGuide(a){const c=a.usageContract;if(!c)return '<div class="reference-note">使用说明待补齐，暂不用于自动选模。</div>';return `<section class="usage-guide"><div class="inspector-section-title">使用说明与调用参数</div><p class="detail-description">${esc(c.summary)}</p><b>适合表达</b><ul>${c.useWhen.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><b>不适合</b><ul>${c.avoidWhen.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${c.capacity?`<p><b>内容容量：</b>${esc(c.capacity)}</p>`:''}${c.duration?`<p><b>原版时长：</b>${c.duration.seconds.toFixed(2)} 秒；${esc(c.duration.note)}</p>`:''}<b>可修改内容</b>${c.parameters.map(p=>`<div class="reference-note"><b>${esc(p.label)}</b> · ${esc({'source-edit':'需改源码','runtime-prop':'运行时传参',selection:'入口选择',consumer:'目标工程配置'}[p.mode])}<br><code>${esc(p.key)}</code><br>${esc(p.binding)}${p.note?'<br>'+esc(p.note):''}</div>`).join('')}<p class="detail-description">${esc(c.styleCompatibility?.note||'')}</p><details><summary>调用示例与限制</summary><pre>${esc(JSON.stringify(c.invocation.example,null,2))}</pre><ul>${c.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>${c.documents?`<a class="button" href="${esc(c.documents.markdown)}" download>下载使用说明</a> <a class="button" href="${esc(c.documents.json)}" download>下载参数协议</a>`:''}</section>`;}
function ingredients(a){if(a.motionOnly)return `<div class="reference-note">几何布局、运动曲线、交错时序与原有光学管线。具体相机、缓动和模糊能力见调用配置；复刻版风格单独保留。</div>`;if(a.productionReady)return `<div class="reference-note">${a.type==='style'?'配色、文字强调与光感。':'布局、背景、运镜、文字弹跳和鱼眼已合并在此模板内部。'}</div>`;const list=[['palette','风格',a.art==='flow'?'炭黑与铜色':a.art==='grid'?'鼠尾草绿':'暖白与墨色'],['layout','布局',a.config.layout==='compact'?'紧凑聚焦':'焦点 → 展开'],['motion','动作',a.config.motion==='linear'?'匀速移动':a.config.motion==='spring'?'轻微回弹':'柔和减速'],['image','背景',a.config.bg==='original'?'预设背景':{warm:'暖沙纸面',dark:'深色空间',sage:'鼠尾草绿'}[a.config.bg]]];return list.map(([i,k,n])=>`<div class="ingredient"><div class="ingredient-icon">${icon(i)}</div><div><b>${esc(n)}</b><span>${k} · 预览参数</span></div>${icon('chevron','arrow')}</div>`).join('')}
function inspector(){const raw=getAsset();const a=raw&&aspectAsset(raw);if(a?.file)return mediaInspector(a);return `<aside class="inspector"><div class="inspector-head"><h2>资产详情</h2><button class="icon-btn" data-action="close-detail" aria-label="关闭详情">${icon('close')}</button></div>${!a?'<div class="inspect-placeholder">选择一个资产，查看预览和详情。</div>':`<div class="inspect-tabs"><button class="${state.detailTab==='info'?'active':''}" data-action="detail-tab" data-value="info">概览</button><button class="${state.detailTab==='spec'?'active':''}" data-action="detail-tab" data-value="spec">调用配置</button><button class="${state.detailTab==='source'?'active':''}" data-action="detail-tab" data-value="source">来源</button></div><div class="inspect-content">${state.detailTab==='info'?`<div class="detail-cover" id="detail-preview">${art(a,true)}</div><button class="button preview-launch" data-action="preview">${icon('expand')}放大预览</button>${a.productionReady?'':`<div class="preview-controls"><button data-action="play" aria-label="播放或暂停">${icon(playing?'pause':'play')}</button><input type="range" id="detail-scrub" min="0" max="1000" value="${progress*1000}" aria-label="预览进度"><span id="detail-time">0.0 / ${a.duration}s</span><button data-action="edit" aria-label="放大预览">${icon('expand')}</button></div>`}<h3 class="detail-title">${esc(a.name)}</h3><p class="detail-description">${esc(a.desc)} 将调好的效果存下来，在下一次创作中继续使用。</p><div class="detail-tags">${a.tags.map(t=>`<span class="chip ${badge(t)}">${esc(t)}</span>`).join('')}</div><div class="meta-grid"><div><label>类型</label><span>${types[a.type]?.[0]}</span></div><div><label>版本</label><span>v${a.version}</span></div><div><label>时长 / 帧率</label><span>${a.duration.toFixed(2)}s / ${a.constraints?.fps||60} fps</span></div><div><label>预览画幅</label><span>${a.productionReady?(a.constraints?.width||720)+' × '+(a.constraints?.height||1280):'16 : 9'}</span></div></div><div class="inspector-section-title">${a.type==='template'?'组合构成':'预览设置'}<small>可在调校中修改</small></div>${ingredients(a)}${usageGuide(a)}<div class="inspector-section-title">归属文件夹<button class="icon-btn" data-action="assign-folder" aria-label="编辑文件夹归属">${icon('plus')}</button></div><div class="detail-tags">${a.folders.length?a.folders.map(f=>`<span class="chip gray">${icon('folder')}${esc(f)}</span>`).join(''):'<span class="muted">尚未归类</span>'}</div><div class="inspector-actions"><button class="button primary" data-action="edit">${icon('filter')}打开调校预览</button><button class="button" data-action="copy">${icon('copy')}复制调用配置</button><button class="button danger" data-action="delete-asset" data-id="${esc(a.id)}">删除资产</button></div><p class="inspector-note">${a.motionOnly?'纯动效与复刻版共用时序；复制配置默认使用纯动效入口。':a.productionReady?'已确认源码资产；预览为原版成片，调用参数可另存。':'演示样例 · CSS 预览，尚未验证为 Remotion 生产资产。'}</p>`:state.detailTab==='spec'?`<div class="inspector-section-title">配置快照<span class="chip peach">${a.productionReady?'REMOTION':'DEMO'}</span></div><p class="detail-description">${a.productionReady?'包含运行包、固定版本与调用参数。':'演示配置用于调校预览，尚不包含 Remotion 源码。'}</p><pre>${esc(JSON.stringify(specification(a),null,2))}</pre><div class="inspector-actions"><button class="button primary" data-action="copy">${icon('copy')}复制 JSON</button><button class="button" data-action="download">${icon('download')}下载配置</button></div>`:`<h3 class="detail-title">资产来源</h3><div class="reference-note">${a.productionReady?esc(a.source?.name||'Eagle')+' · '+esc(a.revisionId)+' · '+esc(a.source?.eagleId):a.type==='reference'?'由你导入的本地参考图片。':a.created>100?'在本原型中创建的组合。':'内置演示资产，用于体验分类、预览与资产调校。不是从参考视频自动提取的预设。'}</div><div class="inspector-section-title">备注</div><p class="detail-description">${esc(a.desc)}</p><button class="button" data-action="rename">${icon('tag')}修改名称与备注</button>`}</div>`}</aside>`}
function render(){const visible=filtered();if(!visible.some(a=>a.id===state.selected)){state.selected=visible[0]?.id;progress=0}const focus=document.activeElement?.id,selection=document.activeElement?.selectionStart;document.body.classList.toggle('collapsed-detail',!state.detail);$('#app').innerHTML=`<div class="shell"><nav class="rail"><button class="brand-icon" data-action="home" aria-label="Motion Archive 首页"><span class="glyph"></span></button><div class="rail-nav"><button class="rail-btn active" data-action="home" title="资产库">${icon('layers')}</button><button class="rail-btn" data-action="all-favorites" title="我的收藏">${icon('star')}</button><button class="rail-btn" data-action="all-assets" title="全部资产">${icon('grid')}</button><div class="rail-sep"></div><button class="rail-btn" data-action="import" title="导入素材">${icon('upload')}</button></div><div class="rail-bottom"><button class="rail-btn" data-action="about" title="原型说明">${icon('info')}</button><button class="avatar" data-action="about" aria-label="本地资源库">GJ</button></div></nav>${sidebar()}${main()}${inspector()}</div>${!state.detail?`<button class="button show-detail" data-action="show-detail">${icon('layout')}详情</button>`:''}`;if(focus==='search'){$('#search').focus();$('#search').setSelectionRange(selection,selection)}}
function download(a){const blob=new Blob([JSON.stringify(specification(a),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const l=document.createElement('a');l.href=url;l.download=a.name+'.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('配置已下载')}
async function copy(a){try{await navigator.clipboard.writeText(JSON.stringify(specification(a),null,2));toast('调用配置已复制')}catch{download(a);toast('无法访问剪贴板，已下载配置文件')}}
let previewReturnFocus=null;
function closeModal(){const wasPreview=modal==='preview';modal=null;draft=null;$('#overlay').innerHTML='';document.body.classList.remove('preview-open');if(wasPreview){render();document.querySelector('.preview-launch')?.focus()}}
function openModal(kind){if(kind==='preview'){previewReturnFocus=document.activeElement;document.querySelectorAll('video').forEach(v=>v.pause());document.body.classList.add('preview-open')}modal=kind;if(kind==='edit'){draft=structuredClone(getAsset());editorTab='content';progress=0;playing=true}renderModal()}
function editorControls(){const c=draft.config;let body='';if(editorTab==='content'){body=`<label class="control-label">主文案<span>使用 / 换行</span></label><input id="edit-title" class="control-input" value="${esc((c.title||'Make it\nmove.').replace(/\n/g,' / '))}" maxlength="50"><label class="control-label">资产名称</label><input id="edit-name" class="control-input" value="${esc(draft.name)}" maxlength="50"><label class="control-label">一句话描述</label><input id="edit-desc" class="control-input" value="${esc(draft.desc)}" maxlength="90"><div class="control-box">文字样例可直接编辑。非文字类样例会保留原有图形，修改的文案仍会存入配置。</div>`}if(editorTab==='style'){body=`<label class="control-label">强调色<span>${esc(c.accent)}</span></label><div class="swatches">${['#8773b2','#e4b195','#a7bd99','#87aecd','#d5acbf'].map(col=>`<button class="swatch ${c.accent===col?'active':''}" style="--swatch:${col}" data-action="swatch" data-value="${col}" aria-label="强调色 ${col}"></button>`).join('')}</div><label class="control-label">自定义颜色</label><input class="control-input" type="color" id="edit-color" value="${esc(c.accent)}"><div class="control-box">强调色会应用于主文字或图形的色彩层。字体与材质库将在下一阶段接入。</div>`}if(editorTab==='motion'){body=`<label class="control-label">动作时长<span id="duration-label">${draft.duration.toFixed(1)}s</span></label><input type="range" id="edit-duration" min="1" max="8" step="0.1" value="${draft.duration}"><label class="control-label">运动幅度<span id="intensity-label">${c.intensity}%</span></label><input type="range" id="edit-intensity" min="0" max="100" value="${c.intensity}"><label class="control-label">运动曲线</label><select class="control-input" id="edit-motion"><option value="ease-out" ${c.motion==='ease-out'?'selected':''}>柔和减速</option><option value="linear" ${c.motion==='linear'?'selected':''}>匀速移动</option><option value="spring" ${c.motion==='spring'?'selected':''}>轻微回弹</option></select><div class="control-box"><b>确定性预览</b><br>同一个进度始终对应同一姿态，可拖动时间轴逐帧查看。这里展示的是二维预览运动。</div>`}if(editorTab==='layout'){body=`<label class="control-label">构图方式</label><select id="edit-layout" class="control-input"><option value="original" ${c.layout==='original'?'selected':''}>原始构图</option><option value="compact" ${c.layout==='compact'?'selected':''}>紧凑聚焦</option><option value="wide" ${c.layout==='wide'?'selected':''}>扩展留白</option></select><div class="control-box">通过主体占比体验布局变化。原型使用统一缩放展示，锚点与多状态动态布局尚未接入。</div>`}if(editorTab==='background'){body=`<label class="control-label">背景选择</label><select id="edit-bg" class="control-input"><option value="original" ${c.bg==='original'?'selected':''}>预设背景</option><option value="warm" ${c.bg==='warm'?'selected':''}>暖沙纸面</option><option value="dark" ${c.bg==='dark'?'selected':''}>深色空间</option><option value="sage" ${c.bg==='sage'?'selected':''}>鼠尾草绿</option></select><div class="control-box">背景可独立替换，不改变文字内容或动作时长。</div>`}return `<div class="editor-tabs">${[['content','内容'],['style','风格'],['motion','动作'],['layout','布局'],['background','背景']].map(([v,l])=>`<button class="${editorTab===v?'active':''}" data-action="editor-tab" data-value="${v}">${l}</button>`).join('')}</div>${body}`}
function renderModal(){if(!modal)return;if(modal==='preview'){renderPreviewModal();return;}if(modal==='edit'&&draft?.file){renderMediaEditor();return;}if(modal==='delete-asset'){const a=getAsset();$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="删除资产"><div class="modal-head"><h2>删除资产</h2></div><div class="modal-body"><p>确定从资产库删除「${esc(a.name)}」？</p><p>此资产将不再出现在列表或 AI 查询结果中。复现历史和已导出的源码包保留。</p><div class="modal-actions"><button class="button" data-action="close-modal">取消</button><button class="button danger" data-action="confirm-delete">确认删除</button></div></div></div></div>`;return;}let html='';if(modal==='edit'&&draft?.productionReady){renderProductionEditor();return;}if(modal==='edit'){html=`<div class="modal edit-modal" role="dialog" aria-modal="true" aria-label="资产调校"><div class="editor-top"><button class="icon-btn" data-action="close-modal" aria-label="返回">${icon('close')}</button><div class="edit-name">${esc(draft.name)}<small>调校预览 · 未保存</small></div><button class="button" data-action="reset-draft">${icon('reset')}还原</button><button class="button primary" data-action="save-draft">${icon('check')}保存修改</button></div><div class="editor-layout"><div class="editor-viewport"><div class="canvas-area"><div class="canvas-stage" id="editor-preview">${art(draft,true)}</div></div><div class="stage-hint"><span>16 : 9 · CSS 交互预览</span><span>修改仅影响当前资产</span></div><div class="timeline"><div class="timeline-top"><button class="icon-btn" data-action="step" data-value="-1" aria-label="上一帧">${icon('previous')}</button><button class="icon-btn" data-action="play" aria-label="播放或暂停">${icon(playing?'pause':'play')}</button><button class="icon-btn" data-action="step" data-value="1" aria-label="下一帧">${icon('next')}</button><span class="time-readout"><b id="editor-frame">000</b> / <span id="editor-total">${Math.round(draft.duration*60)}</span> FRAMES</span><span>60 FPS</span></div><input type="range" id="editor-scrub" min="0" max="1000" value="${progress*1000}" aria-label="拖动预览时间轴"><div class="ruler"><span>0.0s</span><span>${(draft.duration/4).toFixed(1)}</span><span>${(draft.duration/2).toFixed(1)}</span><span>${(draft.duration*.75).toFixed(1)}</span><span>${draft.duration.toFixed(1)}s</span></div></div></div><aside class="editor-controls">${editorControls()}</aside></div></div>`}else{let title='',body='';if(modal==='new-folder'){title='新建文件夹';body='<label for="folder-name">文件夹名称</label><input id="folder-name" placeholder="例如：下一支产品视频" maxlength="24"><p>文件夹只做归类。同一资产可以加入多个文件夹。</p><div class="modal-actions"><button class="button" data-action="close-modal">取消</button><button class="button primary" data-action="save-folder">创建</button></div>'}if(modal==='assign-folder'){title='归类到文件夹';body=`<p>选择这个资产所属的文件夹，不会复制资源。</p>${folders.map(f=>`<label class="check-row"><input type="checkbox" name="folder-check" value="${esc(f)}" ${getAsset().folders.includes(f)?'checked':''}>${icon('folder')}${esc(f)}</label>`).join('')}<div class="modal-actions"><button class="button primary" data-action="save-assignment">保存归类</button></div>`}if(modal==='new-combo'){title='新建动效模板';body='<label>组合名称</label><input id="combo-name" placeholder="给这个效果起个名字" maxlength="40"><label>从一个示例开始</label><select id="combo-template"><option value="make">大字聚焦 · 暖白与紫色</option><option value="flow">轨道跟随 · 炭黑与铜色</option><option value="grid">三卡展开 · 鼠尾草绿</option><option value="feedback">反馈交接 · 终端界面</option><option value="gradient">氛围渐入 · 流动柔光</option></select><p>创建后可以调整内容、背景、运动与构图。</p><div class="modal-actions"><button class="button" data-action="close-modal">取消</button><button class="button primary" data-action="create-combo">创建并调校</button></div>'}if(modal==='rename'){title='修改资产信息';body=`<label>资产名称</label><input id="rename-name" value="${esc(getAsset().name)}" maxlength="50"><label>备注</label><input id="rename-desc" value="${esc(getAsset().desc)}" maxlength="120"><div class="modal-actions"><button class="button primary" data-action="save-rename">保存</button></div>`}if(modal==='import'){title='导入字体 / 背景 / 配置';body=`<label class="dropzone" for="file-input">${icon('upload')}选择自定义文件<small>字体：WOFF2、WOFF、TTF、OTF · 最大 10 MB<br>背景：PNG、JPG、WebP、GIF、MP4、WebM · 最大 50 MB<br>原有 JSON 配置导入仍可使用</small></label><input type="file" id="file-input" accept=".woff2,.woff,.ttf,.otf,.png,.jpg,.jpeg,.webp,.gif,.mp4,.webm,.json" style="display:none"><p>按文件类型自动归入字体或背景，导入后可预览、归类、删除和复制调用配置。</p><div class="modal-actions"><button class="button" data-action="close-modal">取消</button></div>`}if(modal==='about'){title='Motion Archive';body=`<p>一个用来收藏、组合、调校动效资产的库。视频制作留在外部 Remotion 工程。</p><div class="about-feature">${icon('check')}已实现：筛选、收藏、归类、配置导入导出</div><div class="about-feature">${icon('check')}已实现：本地保存、组合参数与时间轴预览</div><div class="about-feature">${icon('clock')}下一阶段：真实资产运行包与 ChatGPT 接口</div><div class="reference-note">这是交互原型。演示资产的“已标定”是样例状态，不代表生产资产已完成验证。清除浏览器数据会删除本地修改，请下载配置备份。</div><div class="modal-actions"><button class="button primary" data-action="close-modal">知道了</button></div>`}html=`<div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div></div>`}$('#overlay').innerHTML=`<div class="modal-backdrop">${html}</div>`;if(modal!=='edit')setTimeout(()=>$('#overlay input:not([type=checkbox]):not([type=file])')?.focus(),30)}
function updateEditor(){if($('#editor-preview'))$('#editor-preview').innerHTML=art(draft,true)}
document.addEventListener('click',async e=>{if(e.target.classList.contains('modal-backdrop')){closeModal();return}const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,value=el.dataset.value,id=el.dataset.id;
 switch(action){
 case 'workflow':location.href='http://127.0.0.1:4180';break;
 case 'home':state={...state,section:'all',folder:null,smart:null,tab:'all',tag:'',query:''};render();break;
 case 'section':state={...state,section:value,folder:null,smart:null,tab:'all',tag:'',query:''};render();break;
 case 'all-assets':state={...state,section:'all',folder:null,smart:null,tab:'all',tag:'',query:''};render();break;
 case 'all-favorites':state={...state,section:'all',folder:null,smart:null,tab:'fav',tag:'',query:''};render();break;
 case 'folder':state={...state,folder:value,smart:null,query:'',tag:'',tab:'all'};render();break;
 case 'smart':state={...state,folder:null,smart:value,query:'',tag:'',tab:'all'};render();break;
 case 'tab':state.tab=value;render();break;case 'view':state.view=value;render();break;case 'filter':state.filter=!state.filter;render();break;case 'tag':state.tag=value;render();break;
 case 'clear':state.query='';state.tag='';state.tab='all';render();break;
 case 'select':{const changed=state.selected!==id||!state.detail;state.selected=id;state.detail=true;if(changed){progress=0;render()}break;}
 case 'delete-asset':state.selected=id;openModal('delete-asset');break;
 case 'confirm-delete':{el.disabled=true;try{await saveQueue;const r=await fetch('/api/library/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:state.selected})});if(!r.ok)throw new Error((await r.json()).error);assets=assets.filter(a=>a.id!==state.selected);closeModal();render();toast('资产已删除');}catch(e){el.disabled=false;toast('删除失败：'+e.message);}break;}
 case 'favorite':{const a=assets.find(a=>a.id===id);a.fav=!a.fav;persist();render();break}
 case 'detail-tab':state.detailTab=value;render();break;
 case 'close-detail':state.detail=false;render();break;case 'show-detail':state.detail=true;render();break;
 case 'focus-search':$('#search').focus();break;
 case 'preview':if(id)state.selected=id;if(getAsset())openModal('preview');break;
 case 'edit':if(getAsset())openModal('edit');break;
 case 'play':playing=!playing;if(modal==='edit')renderModal();else render();break;
 case 'step':playing=false;progress=Math.max(0,Math.min(1,progress+Number(value)/(draft.duration*60)));renderModal();break;
 case 'editor-tab':editorTab=value;$('.editor-controls').innerHTML=editorControls();break;
 case 'swatch':draft.config.accent=value;$('.editor-controls').innerHTML=editorControls();updateEditor();break;
 case 'reset-draft':draft=structuredClone(getAsset());progress=0;renderModal();break;
 case 'save-media':{const a=getAsset();a.name=$('#media-name').value.trim()||a.name;a.desc=$('#media-desc').value;if(a.type==='font')a.config.sample=$('#media-sample').value;else a.config.fit=$('#media-fit').value;await persist();closeModal();render();toast('资产设置已保存');break;}
 case 'save-style':{const a=getAsset();a.name=$('#style-name').value.trim()||a.name;a.desc=$('#style-desc').value;a.usageConfig={...draft.usageConfig};await persist();closeModal();render();toast('风格参数已保存');break;}
 case 'preview-aspect':
 case 'preview-mode':{const scope=modal==='edit'||modal==='preview'?'#overlay':'#detail-preview';const previous=document.querySelector(scope+' video'),time=previous?.currentTime||0,resume=previous&&!previous.paused;if(action==='preview-aspect')aspectModes[id]=value;else previewModes[id]=value;if(modal==='preview')renderPreviewModal();else if(modal==='edit')renderProductionEditor();else render();const next=document.querySelector(scope+' video');if(next){const sync=()=>{next.currentTime=Math.min(time,Math.max(0,next.duration-.02));if(resume)next.play().catch(()=>{});};if(next.readyState>=1)sync();else next.addEventListener('loadedmetadata',sync,{once:true});}break;}
 case 'save-production':{if(getAsset().motionOnly){const a=getAsset();a.name=$('#prod-name').value.trim()||a.name;a.desc=$('#prod-desc').value;await persist();closeModal();render();toast('资产信息已保存');break;}if(getAsset().type==='template'&&(!Number.isFinite(Number($('#prod-lens').value))||Number($('#prod-lens').value)<0||Number($('#prod-lens').value)>.6))return toast('鱼眼强度应为 0–0.6');const a=getAsset();a.name=$('#prod-name').value.trim()||a.name;a.desc=$('#prod-desc').value;a.usageConfig={...a.usageConfig,accent:$('#prod-accent').value,dark:$('#prod-dark').value};if(a.type==='template')Object.assign(a.usageConfig,{fisheyeStrength:Number($('#prod-lens').value),incomeTitle:$('#prod-title').value});await persist();closeModal();render();toast('调用参数已保存；成片预览保留已确认版本');break;}
 case 'save-draft':{const i=assets.findIndex(a=>a.id===draft.id);assets[i]=structuredClone(draft);assets[i].version='1.0.'+(Number(assets[i].version.split('.')[2]||0)+1);assets[i].status='调校中';persist();closeModal();render();toast('修改已保存到本地资源库');break}
 case 'copy':await copy(getAsset());break;case 'download':download(getAsset());break;
 case 'close-modal':closeModal();break;
 case 'new-folder':case 'new-combo':case 'assign-folder':case 'rename':case 'import':case 'about':openModal(action);break;
 case 'save-folder':{const n=$('#folder-name').value.trim();if(!n)return toast('请输入文件夹名称');if(folders.includes(n))return toast('这个文件夹已经存在');folders.push(n);persist();closeModal();render();toast('文件夹已创建');break}
 case 'save-assignment':getAsset().folders=[...document.querySelectorAll('[name=folder-check]:checked')].map(x=>x.value);persist();closeModal();render();toast('归类已保存');break;
 case 'save-rename':{const n=$('#rename-name').value.trim();if(!n)return toast('名称不能为空');getAsset().name=n;getAsset().desc=$('#rename-desc').value.trim();persist();closeModal();render();break}
 case 'create-combo':{const name=$('#combo-name').value.trim();if(!name)return toast('先给组合起个名字');const a=structuredClone(seed.find(a=>a.art===$('#combo-template').value));a.id='custom-'+Date.now();a.name=name;a.status='调校中';a.created=Date.now();a.fav=false;a.folders=state.folder?[state.folder]:[];assets.unshift(a);state.selected=a.id;state.section='template';state.folder=null;state.smart=null;state.query='';state.tag='';state.tab='all';persist();render();openModal('edit');toast('动效模板草稿已创建，可以开始调校');break}
 }
});
document.addEventListener('dblclick',e=>{const card=e.target.closest('.asset-card');if(card&&!e.target.closest('button')){state.selected=card.dataset.id;openModal('edit')}});
document.addEventListener('input',e=>{const id=e.target.id;if(id==='search'){state.query=e.target.value;render()}if(id==='detail-scrub'||id==='editor-scrub'){playing=false;progress=Number(e.target.value)/1000;}if(!draft)return;
 if(id==='edit-title'){draft.config.title=e.target.value.replace(/\s*\/\s*/g,'\n');updateEditor()}if(id==='edit-name')draft.name=e.target.value;if(id==='edit-desc')draft.desc=e.target.value;if(id==='edit-color'){draft.config.accent=e.target.value;updateEditor()}if(id==='edit-duration'){draft.duration=Number(e.target.value);$('#duration-label').textContent=draft.duration.toFixed(1)+'s';$('#editor-total').textContent=Math.round(draft.duration*60)}if(id==='edit-intensity'){draft.config.intensity=Number(e.target.value);$('#intensity-label').textContent=draft.config.intensity+'%'}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='sort'){state.sort=e.target.value;render()}if(draft&&['edit-motion','edit-layout','edit-bg'].includes(id)){draft.config[id.replace('edit-','')]=e.target.value;updateEditor()}if(id==='file-input')importFile(e.target.files[0])});
async function importFile(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.json'))return importMedia(file);if(file.size>3*1024*1024)return toast('请选择小于 3 MB 的文件');try{let a;if(file.name.endsWith('.json')){const data=JSON.parse(await file.text());if(data.schemaVersion!=='prototype-0.1'||!types[data.type]&&!legacyTypes[data.type]||typeof data.name!=='string'||!data.config||typeof data.config!=='object')throw new Error('格式不匹配');const source=seed.find(x=>x.art===data.art)||seed.find(x=>x.id===data.id)||seed[0];if(data.art==='image'&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(data.image||''))throw new Error('图片数据无效');a={...structuredClone(source),name:data.name.slice(0,80),desc:String(data.desc||source.desc).slice(0,200),...(data.art==='image'?{art:'image',image:data.image}:{}),type:['style','background'].includes(data.type)?'style':'template',version:'1.0.0',duration:Math.min(8,Math.max(1,Number(data.durationSeconds)||4)),tags:Array.isArray(data.tags)?data.tags.filter(x=>typeof x==='string').slice(0,8):[],config:{...source.config,title:String(data.config.title||'').slice(0,100),accent:/^#[0-9a-f]{6}$/i.test(data.config.accent)?data.config.accent:source.config.accent,intensity:Math.min(100,Math.max(0,Number(data.config.intensity)||0)),bg:['original','warm','dark','sage'].includes(data.config.bg)?data.config.bg:'original',motion:['ease-out','linear','spring'].includes(data.config.motion)?data.config.motion:'ease-out',layout:['original','compact','wide'].includes(data.config.layout)?data.config.layout:'original'}};}else if(['image/png','image/jpeg','image/webp'].includes(file.type)){const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});a={...structuredClone(seed[0]),name:file.name,type:'style',art:'image',image,desc:'本地导入的参考图片',tags:['参考图片']};}else throw new Error('不支持的格式');a.id='import-'+Date.now();a.created=Date.now();a.folders=[];a.fav=false;a.status='调校中';a.type='template';assets.unshift(a);persist();state={...state,section:a.type,selected:a.id,folder:null,smart:null,tab:'all',query:'',tag:''};closeModal();render();toast('已导入资源库')}catch{toast('无法导入，请选择本原型导出的 JSON 或支持的图片')}}
document.addEventListener('keydown',e=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(e.key==='Escape'){closeModal();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();closeModal();$('#search').focus();return}if(e.key==='Enter'&&e.target.classList.contains('asset-card')){e.target.click();return}if(modal==='edit'&&!draft?.productionReady&&!draft?.file&&!editing){if(e.code==='Space'){e.preventDefault();playing=!playing;renderModal()}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();playing=false;progress=Math.max(0,Math.min(1,progress+(e.key==='ArrowRight'?1:-1)/(draft.duration*60)));renderModal()}}if(modal&&e.key==='Tab'){const items=[...$('#overlay').querySelectorAll('button,input,select,[tabindex]')].filter(x=>x.offsetParent!==null&&!x.disabled);if(items.length){if(e.shiftKey&&e.target===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&e.target===items.at(-1)){e.preventDefault();items[0].focus()}}}});
function animate(ms){const dt=Math.min((ms-last)/1000,.05);last=ms;const a=draft||getAsset();if(a&&!a.file&&!a.productionReady&&playing)progress=(progress+dt/a.duration)%1;const p=progress,conf=a?.config||{};let u=conf.motion==='linear'?p:conf.motion==='spring'?1-Math.exp(-p*7)*Math.cos(p*9):1-Math.pow(1-p,4);const amp=(conf.intensity??45)/100;const factor=conf.layout==='compact'?1.15:conf.layout==='wide'?.8:1;document.querySelectorAll('[data-preview] .moving').forEach(el=>{const tilt=(1-u)*-4*amp;el.style.transform=`translate(${(1-u)*-20*amp}px,${(1-u)*15*amp+Math.sin(p*Math.PI*2)*2}px) scale(${factor*(1.12-u*.12)}) rotate(${tilt}deg)`});document.querySelectorAll('[data-preview] .grid-tiles i').forEach((el,i)=>{const q=Math.max(0,Math.min(1,(p-i*.08)*2));el.style.transform=`translateY(${(1-q)*25}px) rotate(${(1-q)*(i-1)*9}deg)`});document.querySelectorAll('[data-preview] .stack-card').forEach((el,i)=>el.style.transform=`translate(${(i-1)*14*u}%,${i*2}%) rotate(${(-12+i*10)*u}deg)`);if(conf.accent)document.querySelectorAll('[data-preview] .flow-word,[data-preview] .orb-label,[data-preview] .terminal b,[data-preview] .type-lines').forEach(el=>el.style.color=conf.accent);const time=$('#detail-time');if(time)time.textContent=(p*(a?.duration||4)).toFixed(1)+' / '+(a?.duration||4)+'s';const f=$('#editor-frame');if(f&&draft)f.textContent=String(Math.min(Math.floor(p*draft.duration*60),Math.round(draft.duration*60)-1)).padStart(3,'0');for(const id of ['detail-scrub','editor-scrub']){const el=$('#'+id);if(el&&document.activeElement!==el)el.value=p*1000}requestAnimationFrame(animate)}
initLibrary().catch(e=>{$('#app').textContent='资源库读取失败：'+e.message;});

function renderProductionEditor(){if(draft.type==='style'){renderStyleEditor();return;}const a=aspectAsset(draft);if(!a.motionOnly){renderLegacyProductionEditor();return;}$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal edit-modal" role="dialog" aria-modal="true" aria-label="资产预览与调用参数"><div class="editor-top"><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button><div class="edit-name">${esc(a.name)}<small>几何动效 / 原复刻 · ${esc(a.revisionId)}</small></div><a class="button" href="${esc(a.motionOnly.package)}" download>下载纯动效源码</a><button class="button primary" data-action="save-production">保存信息</button></div><div class="editor-layout"><div class="production-stage">${art(a,true)}</div><aside class="editor-controls"><h3>纯动效调用</h3><label class="control-label" for="prod-name">名称</label><input class="control-input" id="prod-name" value="${esc(a.name)}"><label class="control-label" for="prod-desc">备注</label><input class="control-input" id="prod-desc" value="${esc(a.desc)}"><div class="control-box">保留原有运镜、几何层级、缓动、交错时序和模糊管线。字体、照片与材质已替换为中性几何。<br><br>运动参数在源码中编辑；相机、缓动和模糊的实现说明见调用配置。</div><button class="button" data-action="copy">复制纯动效调用配置</button><a class="button" href="${esc(a.package)}" download>下载原复刻源码</a></aside></div></div></div>`;}
function renderLegacyProductionEditor(){if(draft.type==='style'){renderStyleEditor();return;}const a=draft,c={accent:'#d9ff83',dark:'#042f20',fisheyeStrength:.34,incomeTitle:'Track Income',...a.usageConfig};$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal edit-modal" role="dialog" aria-modal="true" aria-label="资产预览与调用参数"><div class="editor-top"><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button><div class="edit-name">${esc(a.name)}<small>已确认 ${esc(a.revisionId)} · v${esc(a.version)}</small></div><a class="button" href="${esc(a.package)}" download>下载源码包</a><button class="button primary" data-action="save-production">保存调用参数</button></div><div class="editor-layout"><div class="production-stage">${art(a,true)}</div><aside class="editor-controls"><h3>管理与调用参数</h3><label class="control-label" for="prod-name">名称</label><input class="control-input" id="prod-name" value="${esc(a.name)}"><label class="control-label" for="prod-desc">备注</label><input class="control-input" id="prod-desc" value="${esc(a.desc)}"><label class="control-label" for="prod-accent">强调色</label><input type="color" id="prod-accent" value="${esc(c.accent)}"><label class="control-label" for="prod-dark">背景色</label><input type="color" id="prod-dark" value="${esc(c.dark)}">${a.type==='template'?`<label class="control-label" for="prod-title">收入镜头文案</label><input class="control-input" id="prod-title" maxlength="28" value="${esc(c.incomeTitle)}"><label class="control-label" for="prod-lens">鱼眼强度 · 0–0.6</label><input id="prod-lens" type="number" min="0" max="0.6" step="0.01" value="${c.fisheyeStrength}">`:''}<div class="control-box">${a.type==='template'?'左侧播放已确认的原版视频。这里保存供 AI / Remotion 使用的参数，不会实时重渲染视频。':'配色可以在当前面板预览，保存后用于下次调用。'}<br>布局、背景和镜头保留在模板内部。</div></aside></div></div></div>`;}
document.addEventListener('input',e=>{if(draft?.productionReady&&['prod-accent','prod-dark'].includes(e.target.id)){draft.usageConfig={...draft.usageConfig,[e.target.id==='prod-accent'?'accent':'dark']:e.target.value};if(draft.type==='style')$('.production-stage').innerHTML=art(draft,true);}});
async function initLibrary(){const response=await fetch('/api/library');if(!response.ok)throw new Error('服务未就绪');const data=await response.json();folders=data.folders;assets=data.items.map(a=>a.productionReady?{...a,desc:a.description,art:a.type==='style'?'palette':'video',tags:a.tags||[a.source?.name||'已确认'],folders:a.folders||[],fav:!!a.fav,duration:(a.constraints?.durationInFrames||Math.round((a.segment?.end-a.segment?.start)*30)||180)/(a.constraints?.fps||30),status:a.verification?.startsWith('agent-')?'授权入库 · 助手检查':'已确认',created:Date.parse(a.createdAt)||101,config:{},usageConfig:a.usageConfig||{}}:a);
 await Promise.all(assets.filter(a=>a.type==='font').map(loadFont));state.selected=assets.find(a=>a.id===new URLSearchParams(location.search).get('asset'))?.id||assets[0]?.id;const requestedAspect=new URLSearchParams(location.search).get('aspect');if(['landscape','portrait'].includes(requestedAspect)&&getAsset()?.aspectVariants?.[requestedAspect])aspectModes[state.selected]=requestedAspect;if(innerWidth<980)state.detail=false;render();requestAnimationFrame(animate);}

async function loadFont(a){try{const face=new FontFace(a.fontFamily,`url("${a.file}")`);await face.load();document.fonts.add(face);}catch{toast('字体加载失败：'+a.name+'，请检查字体文件');}}
async function importMedia(file){try{await saveQueue;toast('正在导入 '+file.name+'…');const r=await fetch('/api/library/import?name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const a=await r.json();if(!r.ok)throw new Error(a.error);if(a.type==='font')await loadFont(a);assets.unshift(a);state={...state,section:a.type,selected:a.id,folder:null,smart:null,tab:'all',query:'',tag:'',detail:true};closeModal();render();toast('已导入'+types[a.type][0]+'，可复制调用配置');}catch(e){toast('导入失败：'+e.message);}}
function mediaInspector(a){return `<aside class="inspector"><div class="inspector-head"><h2>${types[a.type][0]}详情</h2><button class="icon-btn" data-action="close-detail" aria-label="关闭详情">${icon('close')}</button></div><div class="inspect-content"><div class="detail-cover">${art(a,true)}</div><h3 class="detail-title">${esc(a.name)}</h3><p>${esc(a.desc)}</p><p class="detail-description">${esc(a.originalName)} · ${(a.bytes/1024/1024).toFixed(2)} MB</p><div class="inspector-section-title">归属文件夹<button class="icon-btn" data-action="assign-folder" aria-label="编辑文件夹归属">${icon('plus')}</button></div><p>${a.folders.map(esc).join(' / ')||'尚未归类'}</p><div class="inspector-actions"><button class="button primary" data-action="edit">预览与设置</button><button class="button" data-action="copy">复制调用配置</button><button class="button" data-action="download">下载配置 JSON</button><a class="button" href="${esc(a.file)}" download="${esc(a.originalName)}">下载原文件</a><button class="button danger" data-action="delete-asset" data-id="${a.id}">删除资产</button></div>${usageGuide(a)}<div class="inspector-section-title">调用配置</div><pre>${esc(JSON.stringify(specification(a),null,2))}</pre></div></aside>`;}
function renderMediaEditor(){const a=draft;$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal edit-modal" role="dialog" aria-modal="true" aria-label="字体与背景设置"><div class="editor-top"><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button><div class="edit-name">${esc(a.name)}</div><button class="button primary" data-action="save-media">保存设置</button></div><div class="editor-layout"><div class="production-stage" id="media-stage">${art(a,true)}</div><aside class="editor-controls"><label for="media-name">名称</label><input class="control-input" id="media-name" value="${esc(a.name)}"><label for="media-desc">备注</label><input class="control-input" id="media-desc" value="${esc(a.desc)}">${a.type==='font'?`<label for="media-sample">试字内容</label><textarea id="media-sample" maxlength="300">${esc(a.config.sample)}</textarea><p>字体缺少的字符会使用系统字体显示。</p>`:`<label for="media-fit">画面适配</label><select id="media-fit"><option value="cover" ${a.config.fit==='cover'?'selected':''}>铺满画面</option><option value="contain" ${a.config.fit==='contain'?'selected':''}>完整显示</option></select>`}</aside></div></div></div>`;}
document.addEventListener('input',e=>{if(!draft?.file)return;if(e.target.id==='media-sample'){draft.config.sample=e.target.value;$('#media-stage').innerHTML=art(draft,true);}});
document.addEventListener('change',e=>{if(draft?.file&&e.target.id==='media-fit'){draft.config.fit=e.target.value;$('#media-stage').innerHTML=art(draft,true);}});

function styleArt(a){const spec=resolvedStyle(a);if(!spec)return '<div class="art font-sample">风格参数缺失，请重新提取</div>';const colors=spec.palette,bg=colors[spec.preview.background],fg=colors[spec.preview.foreground];return `<div class="art production-style ${spec.preview.material==='frosted-glass'?'glass-style':''}" style="background:${esc(bg)};color:${esc(fg)};--glass-accent:${esc(colors.accent)};--glass-glow:${esc(colors.highlight||'#ffffff')}"><small>${esc(spec.label)}</small><strong>${esc(spec.sample).replace(/\n/g,'<br>')}</strong>${spec.preview.material==='frosted-glass'?'<div class="style-glass-orb"></div>':''}<div class="palette-strip">${Object.entries(colors).map(([key,value])=>`<i title="${esc(key)} ${esc(value)}" style="background:${esc(value)}"></i>`).join('')}</div></div>`;}
function renderStyleEditor(){const a=draft,spec=resolvedStyle(a);$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal edit-modal" role="dialog" aria-modal="true" aria-label="风格调校"><div class="editor-top"><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button><div class="edit-name">${esc(a.name)}</div><button class="button primary" data-action="save-style">保存风格参数</button></div><div class="editor-layout"><div class="production-stage" id="style-stage">${styleArt(a)}</div><aside class="editor-controls"><label for="style-name">名称</label><input class="control-input" id="style-name" value="${esc(a.name)}"><label for="style-desc">备注</label><input class="control-input" id="style-desc" value="${esc(a.desc)}">${Object.entries(spec?.palette||{}).map(([key,value])=>`<label for="style-${esc(key)}">${({light:'浅色背景',dark:'深色背景',accent:'强调色',ink:'文字色',highlight:'高光色',surface:'卡片底色'})[key]||esc(key)} · ${esc(value)}</label><input id="style-${esc(key)}" type="color" data-style-key="${esc(key)}" value="${esc(value)}">`).join('')}<h3>字体与材质</h3><pre>${esc(JSON.stringify({typography:spec?.typography,material:spec?.material,background:spec?.background},null,2))}</pre><p>预览为风格样板；完整动效以复刻视频为准。</p></aside></div></div></div>`;}
document.addEventListener('input',e=>{const key=e.target.dataset?.styleKey;if(key&&draft?.styleSpec){draft.usageConfig={...draft.usageConfig,[key]:e.target.value};$('#style-stage').innerHTML=styleArt(draft);}});

function renderPreviewModal(){
 const raw=getAsset();const a=raw&&aspectAsset(raw);if(!a)return;
 $('#overlay').innerHTML=`<div class="modal-backdrop preview-backdrop"><section class="modal preview-modal" role="dialog" aria-modal="true" aria-label="${esc(a.name)} · 大屏预览"><header class="preview-modal-header"><div><h2>${esc(a.name)}</h2><span>${a.constraints?.width||1920} × ${a.constraints?.height||1080} · ${a.duration.toFixed(1)}s</span></div><button class="icon-btn" data-action="close-modal" aria-label="关闭预览">${icon('close')}</button></header><div class="preview-modal-stage">${art(a,true)}</div><footer class="preview-modal-footer">拖动视频进度条查看细节<span>ESC 关闭</span></footer></section></div>`;
 $('#overlay [data-action="close-modal"]').focus();
}
